media.css:
[data-ui-unit="media"].product-media {
  margin: 0;
  border-radius: 0;
}

[data-ui-unit="media"].product-media img {
  display: block;
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  object-position: 44% center;
}

@media (min-width: 701px) {
  [data-ui-unit="media"].product-media {
    border-radius: 8px;
  }

  [data-ui-unit="media"].product-media img {
    border-radius: 8px;
  }
}

identity.css:
[data-ui-unit="identity"].product-identity {
  padding-top: 24px;
  padding-bottom: 24px;
}

[data-ui-unit="identity"].product-identity .eyebrow {
  font-size: 14px;
  color: #60606a;
  margin-bottom: 8px;
}

[data-ui-unit="identity"].product-identity .title {
  font-size: 22px;
  font-weight: 700;
  line-height: 1.45;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

[data-ui-unit="identity"].product-identity .price-row {
  margin-top: 12px;
}

[data-ui-unit="identity"].product-identity .price {
  display: block;
  font-size: 24px;
  font-weight: 800;
  word-break: keep-all;
}

[data-ui-unit="identity"].product-identity .metadata {
  margin-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

[data-ui-unit="identity"].product-identity .meta-item {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  color: #555560;
  word-break: keep-all;
}

[data-ui-unit="identity"].product-identity .meta-item img {
  width: 20px;
  height: 20px;
  display: block;
}

[data-ui-unit="identity"].product-identity .description {
  margin-top: 20px;
  font-size: 15px;
  line-height: 1.75;
  word-break: keep-all;
  overflow-wrap: anywhere;
}

@media (min-width: 701px) {
  [data-ui-unit="identity"].product-identity {
    padding-top: 0;
  }

  [data-ui-unit="identity"].product-identity .title {
    font-size: 28px;
  }
}

booking.css:
[data-ui-unit="booking"]#booking-layout {
  padding-top: 20px;
  border-top: 1px solid #ededf0;
}

[data-ui-unit="booking"] .booking-host-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  color: #202024;
}

[data-ui-unit="booking"] .booking-host-subtitle {
  margin: 4px 0 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.5;
}

[data-ui-unit="booking"] .booking-icon-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  padding: 0;
  margin: 0;
  border: none;
  background-color: transparent;
  cursor: pointer;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}

[data-ui-unit="booking"] .booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  color: #60606a;
  transition: color 0.2s ease, transform 0.1s ease;
}

[data-ui-unit="booking"] .booking-icon-btn:hover img {
  color: #5146d7;
}

[data-ui-unit="booking"] .booking-icon-btn:active img {
  transform: scale(0.92);
}

[data-ui-unit="booking"] .booking-icon-btn[aria-pressed="true"] img {
  color: #5146d7;
}

[data-ui-unit="booking"] .booking-icon-btn:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
  border-radius: 4px;
}

[data-ui-unit="booking"] #booking-actions > button:last-child {
  min-height: 52px;
  padding: 12px 16px;
  background-color: #5146d7;
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  border-radius: 6px;
  border: none;
  text-align: center;
  width: 100%;
  cursor: pointer;
  transition: background-color 0.2s ease, transform 0.1s ease;
}

[data-ui-unit="booking"] #booking-actions > button:last-child:hover {
  background-color: #4339b8;
}

[data-ui-unit="booking"] #booking-actions > button:last-child:active {
  transform: scale(0.98);
}

[data-ui-unit="booking"] #booking-actions > button:last-child:focus-visible {
  outline: 3px solid #5146d7;
  outline-offset: 2px;
}

[data-ui-unit="booking"] .booking-note {
  margin: 12px 0 0;
  font-size: 14px;
  color: #60606a;
  line-height: 1.6;
}
